$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\public_sources.py"
$testPath = Join-Path $pkg "tests\test_public_sources.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found: $python" }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-017" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-017"
        title = "Connect verified public opportunity feeds"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Inside ahos_core only, configure verified public read-only Remote OK and We Work Remotely RSS feeds and add resilient per-source collection into the local opportunity candidate store. A failed feed must not stop the other feeds. Tests must use injected local data and make no real network calls. No applications, outreach, posting, login, payments, purchases, or other external write actions."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

Write-Host "=== AHOS-017 PUBLIC SOURCE CONNECTORS ==="
Write-Host "Adding Remote OK + We Work Remotely source catalog."
Write-Host "Tests use injected data: NO real network and NO OpenAI API calls."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}

if ($testExit -ne 0) { throw "AHOS-017 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-017" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/public_sources.py ahos_core/tests/test_public_sources.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): connect verified public opportunity feeds"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-017 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-017 -> completed"
Write-Host "Git push: PASS"
Write-Host "Real network calls during this installer: 0"
Write-Host "OpenAI API calls: 0"
